// T8 integrated acceptance runner. Reads a step table. Does not write the table.
// controls: K1 and K2. accept: K1, K2, c1, c2, store compare, reopen.
// Do not edit this file after it has run.
// Usage: node26 work/scripts/accept_t8_v1.mjs om-emu controls|accept <table.json> <tag>
import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { runZone } from '../../ref/analysis/button-af/readiness/t5-afon-button-handoff/scripts/zone_session_k1.mjs';
import { attachPose } from '../../ref/tasks/T7-orientation-producer/run-20261119-072701/work/scripts/pose.mjs';
import { compareStores, judgeFreshSaves, readStore, titleBand } from '../../ref/analysis/button-af/readiness/t3m-afon-editor-state-leak/scripts/accept_lib_v4.mjs';

const [checkout, mode, tablePath, tag] = process.argv.slice(2);
if (!checkout || (mode !== 'controls' && mode !== 'accept') || !tablePath || !tag) {
  process.stderr.write('usage: node26 work/scripts/accept_t8_v1.mjs om-emu controls|accept <table.json> <tag>\n');
  process.exit(2);
}

const GETTER = 0x60063380;
const SETTER = 0x60063431;
const EDITOR_COPY = 0x6119af02;
const GLOBAL_POS = 0x60379d64;
const SHADOW_POS = 0x62953c10;
const SIZE_REC = 0x62954108;
const SIZE_N = 72;
const RECORD = 16;
const SHADOW_N = 4;
const OBJECT_OFF = 0x42;
const MODE = 0xa031eef7;
const MODE_CACHED = 0x6031eef7;
const PROFILE = 0xa031e920;
const PROFILE_CACHED = 0x6031e920;
const EXT = 0xa031eeb0;
const EXT_CACHED = 0x6031eeb0;
const DIRECT = 0x0405;
const MENU = 0x0b02;
const POSE = 0xa32c568c;
const RET_ZONE = 0x60a8f71c;
const RET_SIZE = 0x60a8f757;
const RET_POS = 0x60a8f76e;
const RET_PLUS9 = 0x60a8f789;
const CALL_CONV = 0x60a8f71f;
const BACK_CONV = 0x60a8f726;
const LAYOUT = {
  0x99a1: { off: 0x00, n: 8, width: 1 },
  0x9a41: { off: 0x08, n: 2, width: 1 },
  0x5962: { off: 0x0a, n: 6, width: 2 },
  0x1dd1: { off: 0x16, n: 10, width: 1 },
  0x84d1: { off: 0x20, n: 1, width: 1 },
  0x88b2: { off: 0x22, n: 1, width: 2 },
  0x90d1: { off: 0x24, n: 8, width: 1 },
  0x5a11: { off: 0x2c, n: 11, width: 1 },
  0x1de1: { off: 0x37, n: 8, width: 1 },
  0x1df1: { off: 0x3f, n: 8, width: 1 },
};
const LIVE = {
  k99a1: { addr: 0x6295946c, n: 8, w: 1 },
  k9a41: { addr: 0x62959484, n: 2, w: 1 },
  k5962: { addr: 0x62920bf0, n: 6, w: 2 },
  k1dd1: { addr: 0x62920982, n: 10, w: 1 },
  k84d1: { addr: 0x62920fa5, n: 1, w: 1 },
  k88b2: { addr: 0x629526c0, n: 1, w: 2 },
  k90d1: { addr: 0x62959355, n: 8, w: 1 },
  k5a11: { addr: 0x62920c18, n: 11, w: 1 },
  k1de1: { addr: 0x6292098c, n: 8, w: 1 },
  k1df1: { addr: 0x62920994, n: 9, w: 1 },
};
const PERSIST = [211472, 211476, 211480, 211484, 211504, 211508, 211512, 211516];
const POSE_SHA = '09cb38618024a749ba4b15ee3be4e5140257d6c5145347567887196a81665358';
const OVERLAY = 'work/out/overlay-combined-t8.csv';
const ROLES = mode === 'controls' ? ['k1', 'k2'] : ['k1', 'k2', 'c1', 'c2'];

const table = JSON.parse(readFileSync(resolve(tablePath), 'utf8'));
const outJsonl = resolve('work/out/' + tag + '.jsonl');
const inventoryPath = resolve('work/out/import-inventory-' + tag + '.json');
for (const role of ROLES) {
  for (const phase of ['', '-reopen']) {
    const p = resolve('work/out/session-' + tag + '-' + role + phase + '.jsonl');
    const n = resolve('work/out/nvram-' + tag + '-' + role + '.json');
    if (existsSync(p) || existsSync(n)) {
      process.stderr.write('refusing to overwrite ' + (existsSync(p) ? p : n) + '\n');
      process.exit(2);
    }
  }
}
if (existsSync(outJsonl) || existsSync(inventoryPath)) {
  process.stderr.write('refusing to overwrite an existing output\n');
  process.exit(2);
}
mkdirSync(resolve('work/out'), { recursive: true });

const lines = [];
function emit(row) {
  lines.push(JSON.stringify(row));
  writeFileSync(outJsonl, lines.join('\n') + '\n');
  const brief = { id: row.id, pass: row.pass };
  if (row.problems && row.problems.length) brief.problems = row.problems.slice(0, 8);
  console.log(JSON.stringify(brief));
}

const holder = { events: [], queue: [] };
const dynamicImports = [];

function sameRole(role) { return role === 'c1' || role === 'c2'; }

function resolveValue(value, role, step, field, depth) {
  if (depth > 6) throw new Error('missing reference cycle ' + step.id + ' ' + field);
  if (value && typeof value === 'object' && !Array.isArray(value)) {
    if (value.from) {
      const id = value.step || step.id;
      const src = table.steps.find((s) => s.id === id);
      if (!src || !(field in src.expect)) throw new Error('missing reference ' + id + ' ' + field + ' from ' + value.from);
      return resolveValue(src.expect[field], value.from, src, field, depth + 1);
    }
    if (value.preset) {
      if (!table.presets || !(value.preset in table.presets)) throw new Error('missing preset ' + value.preset);
      return table.presets[value.preset];
    }
    if (Object.prototype.hasOwnProperty.call(value, role)) return resolveValue(value[role], role, step, field, depth + 1);
    if (sameRole(role) || role === 'k2') {
      if (Object.prototype.hasOwnProperty.call(value, 'overlay')) return resolveValue(value.overlay, role, step, field, depth + 1);
    }
    const roleKeys = ['k1', 'k2', 'c1', 'c2', 'overlay'];
    if (roleKeys.some((k) => Object.prototype.hasOwnProperty.call(value, k))) {
      throw new Error('missing reference ' + step.id + ' ' + field + ' for ' + role);
    }
  }
  return value;
}

function diffValue(path, exp, got, problems) {
  if (Array.isArray(exp)) {
    if (!Array.isArray(got) || got.length !== exp.length) {
      problems.push(path + ' length expected ' + exp.length + ' actual ' + (got ? got.length : 'none'));
      return;
    }
    for (let i = 0; i < exp.length; i++) {
      if (exp[i] !== got[i]) problems.push(path + '[' + i + '] expected ' + exp[i] + ' actual ' + got[i]);
    }
    return;
  }
  if (exp && typeof exp === 'object') {
    for (const key of Object.keys(exp)) diffValue(path + '.' + key, exp[key], got ? got[key] : undefined, problems);
    return;
  }
  if (exp !== got) problems.push(path + ' expected ' + JSON.stringify(exp) + ' actual ' + JSON.stringify(got));
}

function readLive(ctx, addr, n, w) {
  const out = [];
  for (let i = 0; i < n; i++) {
    if (w === 2) {
      const b = ctx.l.sim.read(addr + i * 2, 2);
      out.push(b[0] | (b[1] << 8));
    } else out.push(ctx.l.sim.read(addr + i, 1)[0]);
  }
  return out;
}
function callSaved(ctx, fn) {
  const saved = ctx.l.sim.registers();
  try { return fn(); }
  finally { ctx.l.sim.reset(saved); }
}
function readGetter(ctx, key, index) {
  return callSaved(ctx, () => ctx.l.call(ctx.native(GETTER), { d0: key, d1: index, a0: 0 }, null, null, 200000).d0 & 0xffff);
}
function setKey(ctx, key, index, value) {
  callSaved(ctx, () => ctx.l.call(ctx.native(SETTER), { d0: key, d1: index, a1: value }, null, null, 200000));
}
function snapshot(ctx, view) {
  const half = {};
  for (const [name, row] of Object.entries(LIVE)) half[name] = readLive(ctx, row.addr, row.n, row.w);
  half.k1db1 = [readGetter(ctx, 0x1db1, 0)];
  half.k1dc1 = [readGetter(ctx, 0x1dc1, 0)];
  const own = ctx.readOwn();
  return {
    title: view.title, highlight: view.highlight, screen: view.screen,
    mirror: Array.from(ctx.l.sim.read(EXT, 55)),
    zone: ctx.readByte(PROFILE), zoneCached: ctx.readByte(PROFILE_CACHED),
    flag: ctx.readByte(MODE), flagCached: ctx.readByte(MODE_CACHED),
    half, subject: readGetter(ctx, 0x1e71, 0),
    focus: ctx.s.get(289), active: ctx.s.get(25),
    status: own[5], owner: own[4], enabled: own[6],
    target: ctx.readTarget(),
    sizeRecord: Array.from(ctx.l.sim.read(SIZE_REC, SIZE_N)),
    screenshot: view.file,
  };
}

let png = null;
function capture(ctx, role, id) {
  let view = { texts: [], highlight: null, frame: null, error: null };
  try { view = ctx.screen(); }
  catch (e) { view = { texts: [], highlight: null, frame: null, error: String(e && e.message || e) }; }
  const frame = (view && view.frame) || ctx.s.frame('boundary');
  if (!frame) throw new Error('screenshot failed at ' + role + ' ' + id + (view && view.error ? ': ' + view.error : ''));
  const file = resolve('work/out/' + tag + '-' + role + '-' + id + '.png');
  png.write_png(file, frame[0], frame[1], png.words_to_rgb(frame[2]));
  return {
    title: titleBand(frame),
    highlight: view && view.highlight != null ? view.highlight : null,
    texts: (view && view.texts) || [],
    screen: ctx.s.screen(),
    file: file.split(/[/\\]/).pop(),
  };
}

function installCombined(ctx, modelMod, menuMod) {
  const l = ctx.l;
  const readByte = (a) => l.sim.read(a, 1)[0];
  const writeByte = (a, v) => { l.sim.write(a >>> 0, Buffer.from([v & 0xff])); };
  const readU16 = (a) => { const b = l.sim.read(a, 2); return b[0] | (b[1] << 8); };
  const writeU16 = (a, v) => { const b = Buffer.alloc(2); b.writeUInt16LE(v & 0xffff, 0); l.sim.write(a >>> 0, b); };
  const readBytes = (a, n) => Buffer.from(l.sim.read(a, n));
  const writeBytes = (a, buf) => { try { l.sim.write(a >>> 0, buf); return true; } catch (e) { return String(e && e.message || e); } };
  const aliasOf = (addr) => {
    const a = addr >>> 0;
    if (a >= 0x60000000 && a < 0x80000000) return (a + 0x40000000) >>> 0;
    if (a >= 0xa0000000 && a < 0xc0000000) return (a - 0x40000000) >>> 0;
    return null;
  };
  const st = { zoneSnap: null, sizeOpen: false, inited: false, globalSnap: null, shadowSnap: null, heldPos: null, sizeSnap: null };
  let editorObj = null;
  let copiesWhileFlag = 0;
  let armCopy = false;
  let inConv = false;
  const link = { area: 0, pos: 0 };
  const counts = { zone: 0, size: 0, pos: 0, plus9: 0, dim: 0 };
  const slotAddr = (key, index) => {
    const row = LAYOUT[key];
    if (!row || index >= row.n) return null;
    return (EXT + row.off + index * row.width) >>> 0;
  };
  const initMirror = () => {
    if (st.inited || readByte(MODE) !== 1) return;
    st.inited = true;
    for (const row of Object.values(LAYOUT)) {
      for (let i = 0; i < row.n; i++) {
        const addr = EXT + row.off + i * row.width;
        if (row.width === 2) { if (readU16(addr) === 0xffff) writeU16(addr, 0); }
        else if (readByte(addr) === 0xff) writeByte(addr, 0);
      }
    }
  };
  const noteEntry = () => {
    if (readByte(MODE) === 1 && st.zoneSnap === null) {
      st.zoneSnap = readByte(PROFILE);
      st.globalSnap = readBytes(GLOBAL_POS, RECORD);
      st.shadowSnap = readBytes(SHADOW_POS, SHADOW_N);
      st.sizeSnap = readBytes(SIZE_REC, SIZE_N);
      st.heldPos = readU16(LIVE.k5962.addr + 2);
      editorObj = null;
      copiesWhileFlag = 0;
      armCopy = false;
    }
  };
  const restoreLeaks = (why) => {
    const log = { why, editor: editorObj ? (editorObj >>> 0).toString(16) : null };
    if (st.globalSnap) {
      log.global = writeBytes(GLOBAL_POS, st.globalSnap);
      log.globalAlias = writeBytes(aliasOf(GLOBAL_POS), st.globalSnap);
    }
    if (st.shadowSnap) {
      log.shadow = writeBytes(SHADOW_POS, st.shadowSnap);
      log.shadowAlias = writeBytes(aliasOf(SHADOW_POS), st.shadowSnap);
    }
    if (st.sizeSnap) {
      log.size = writeBytes(SIZE_REC, st.sizeSnap);
      const sizeAlias = aliasOf(SIZE_REC);
      if (sizeAlias !== null) log.sizeAlias = writeBytes(sizeAlias, st.sizeSnap);
    }
    if (editorObj && st.heldPos !== null) {
      const at = (editorObj + OBJECT_OFF) >>> 0;
      const rec = readBytes(at, RECORD);
      rec.writeUInt16LE(st.heldPos & 0xffff, 0);
      log.object = writeBytes(at, rec);
      const al = aliasOf(editorObj);
      if (al !== null) log.objectAlias = writeBytes((al + OBJECT_OFF) >>> 0, rec);
    }
    return log;
  };
  const leave = (why) => {
    if (readByte(MODE) !== 1) return false;
    const restore = st.zoneSnap === null ? readByte(PROFILE) : st.zoneSnap;
    writeByte(MODE, 0);
    writeByte(MODE_CACHED, 0);
    writeByte(PROFILE, restore);
    writeByte(PROFILE_CACHED, restore);
    restoreLeaks('leave-' + why);
    armCopy = copiesWhileFlag === 0;
    st.zoneSnap = null;
    st.sizeSnap = null;
    st.sizeOpen = false;
    st.inited = false;
    return true;
  };
  const refresh = () => {
    link.area = readGetter(ctx, 0x1db1, 0);
    link.pos = readGetter(ctx, 0x1dc1, 0);
  };
  const bank = () => {
    if (!(link.area === 1 && link.pos === 1)) return 1;
    const pose = l.sim.u32(POSE) >>> 0;
    if (pose === 2) return 5;
    if (pose === 4) return 3;
    return 1;
  };
  l.observe(ctx.native(CALL_CONV), () => { inConv = true; }, 'obs-builder-converter');
  l.observe(ctx.native(BACK_CONV), () => { inConv = false; }, 'obs-builder-converter-back');
  l.hook(ctx.native(GETTER), (h, r) => {
    if (armCopy && readByte(MODE) !== 1 && ((l.state() & 0xffff) === DIRECT)) armCopy = false;
    initMirror();
    noteEntry();
    const back = r.mdr >>> 0;
    const key = r.d0 & 0xffff;
    const index = r.d1 & 0xffff;
    const b = bank();
    if (back === RET_ZONE) {
      counts.zone += 1;
      let v = readByte(EXT + b);
      if (v === 0xff) v = readByte(PROFILE);
      h.finish(r, { d0: v });
      return;
    }
    if (back === RET_SIZE) {
      counts.size += 1;
      let v = readByte(EXT + 0x08);
      if (v === 0xff) v = 0;
      h.finish(r, { d0: v });
      return;
    }
    if (back === RET_POS) {
      counts.pos += 1;
      let v = readU16(EXT + 0x0a + b * 2);
      if (v === 0xffff) v = 0;
      h.finish(r, { d0: v });
      return;
    }
    if (back === RET_PLUS9) { counts.plus9 += 1; h.finish(r, { d0: 0 }); return; }
    if (inConv && key === 0x1dd1) {
      counts.dim += 1;
      let v = readByte(EXT + 0x16 + (index & 0xff));
      if (v === 0xff) v = 0;
      h.finish(r, { d0: v });
      return;
    }
    const addr = readByte(MODE) === 1 ? slotAddr(key, index) : null;
    if (addr === null) { l.passthrough(r); return; }
    const ret = LAYOUT[key].width === 2 ? readU16(addr) : readByte(addr);
    h.finish(r, { d0: ret });
  }, 'EMULATOR-ONLY combined profile read and editor routing. Role: behaviour.');
  l.hook(ctx.native(SETTER), (h, r) => {
    initMirror();
    noteEntry();
    const key = r.d0 & 0xffff;
    const index = r.d1 & 0xffff;
    const addr = readByte(MODE) === 1 ? slotAddr(key, index) : null;
    if (addr === null) { l.passthrough(r); return; }
    if (LAYOUT[key].width === 2) writeU16(addr, r.a1 >>> 0);
    else writeByte(addr, r.a1 >>> 0);
    if (key === 0x99a1 && (index === 0 || index === 1)) {
      writeByte(PROFILE, r.a1 & 0xff);
      writeByte(PROFILE_CACHED, r.a1 & 0xff);
    }
    h.finish(r, { d0: 0 });
  }, 'EMULATOR-ONLY editor setter routing. Role: behaviour.');
  const pendingCopy = new Map();
  l.hook(ctx.native(EDITOR_COPY), (h, r) => {
    const flag = readByte(MODE) === 1;
    const armed = flag || armCopy;
    if (flag) copiesWhileFlag += 1;
    if (armed && (r.a0 >>> 0) >= 0x60000000) editorObj = r.a0 >>> 0;
    const mdr = r.mdr >>> 0;
    if (armed && mdr) {
      pendingCopy.set(mdr, { flag, arm: armCopy });
      if (!l.hooks.has(mdr)) {
        try {
          l.hook_rt(mdr, (_hh, rr) => {
            const job = pendingCopy.get(mdr);
            pendingCopy.delete(mdr);
            if (job && job.flag) restoreLeaks('copy-while-flag');
            else if (job && job.arm) { restoreLeaks('copy-after-leave'); armCopy = false; }
            l.passthrough(rr);
          }, 'EMULATOR-ONLY exit: editor copy returned');
        } catch { pendingCopy.delete(mdr); }
      }
    }
    l.passthrough(r);
  }, 'EMULATOR-ONLY exit: restore editor position copies and the 72-byte record. Role: behaviour.');
  const [fromReg, toReg] = modelMod.fact('state_log.regs', ['a0', 'a1']);
  l.wrap(menuMod.STATE_LOG, (prev) => (h, r) => {
    const event = r.d0 >>> 0;
    const oldSt = (r[fromReg] >>> 0) & 0xffff;
    const newSt = (r[toReg] >>> 0) & 0xffff;
    const result = prev(h, r);
    if (readByte(MODE) === 1 && oldSt === DIRECT && newSt !== DIRECT) leave('direct-' + (event & 0xffff).toString(16));
    else if (readByte(MODE) === 1 && oldSt === MENU) {
      const ev = event & 0xffff;
      if (ev === 0x900b) st.sizeOpen = true;
      else if (st.sizeOpen && (ev === 0x900d || ev === 0x900e)) leave('size-' + ev.toString(16));
    }
    return result;
  }, 'EMULATOR-ONLY exit: clear the flag and restore the zone byte. Role: behaviour.');
  let shutdownEntry = null;
  try { shutdownEntry = modelMod.fact('power.off')?.shutdown?.entry >>> 0; } catch { shutdownEntry = null; }
  if (shutdownEntry) l.observe(shutdownEntry, () => { leave('session-end'); }, 'EMULATOR-ONLY exit: session-end shutDown');
  const enter = () => {
    if (readByte(MODE) === 1) throw new Error('enter while the flag is set');
    st.sizeOpen = false;
    st.zoneSnap = null;
    st.inited = false;
    st.globalSnap = null;
    st.shadowSnap = null;
    st.sizeSnap = null;
    st.heldPos = null;
    editorObj = null;
    copiesWhileFlag = 0;
    armCopy = false;
    writeByte(MODE, 1);
    writeByte(MODE_CACHED, 1);
    readGetter(ctx, 0x99a1, 0);
  };
  return { refresh, counts, enter, readByte };
}

function judgeStep(role, step, actual, pose) {
  const fields = ['title', 'highlight', 'screen', 'mirror', 'zone', 'flag', 'half', 'subject', 'focus', 'active', 'status'];
  if (step.action === 'edge') fields.push('target', 'owner', 'enabled');
  if ('sizeRecord' in step.expect) fields.push('sizeRecord');
  if ('persisted' in step.expect) fields.push('persisted');
  const expected = {};
  const problems = [];
  let checked = 0;
  for (const field of fields) {
    if (!(field in step.expect) && field !== 'highlight') continue;
    if (!(field in step.expect)) continue;
    const exp = resolveValue(step.expect[field], role, step, field, 0);
    expected[field] = exp;
    if (field === 'zone') {
      diffValue('zone', exp, actual.zone, problems);
      diffValue('zoneCached', exp, actual.zoneCached, problems);
    } else if (field === 'flag') {
      diffValue('flag', exp, actual.flag, problems);
      diffValue('flagCached', exp, actual.flagCached, problems);
    } else diffValue(field, exp, actual[field], problems);
    checked += 1;
  }
  if ('poseIndex' in step.expect) {
    expected.poseIndex = step.expect.poseIndex;
    expected.poseExif = step.expect.poseExif;
    if (pose) {
      diffValue('poseIndex', step.expect.poseIndex, pose.index, problems);
      diffValue('poseExif', step.expect.poseExif, pose.exif, problems);
      if ('poseWord' in step.expect) diffValue('poseWord', step.expect.poseWord, pose.word, problems);
    } else problems.push('pose missing');
    checked += 1;
  }
  if (!checked) throw new Error('no fields checked ' + step.id);
  return { expected, problems };
}

async function installWitness(menuMod) {
  const proto = menuMod.MenuLab.prototype;
  if (proto.__t8SaveWitness) return;
  const orig = proto._s_nand_write;
  proto._s_nand_write = function(hle, r, posted) {
    const before = this.store_log && this.store_log.nvram ? this.store_log.nvram.saves.length : 0;
    const origAfter = hle.finish_after.bind(hle);
    const origFinish = hle.finish.bind(hle);
    const rec = { store: null, from: null, posted: !!posted, via: null, intended: null, status: null, callback: null, sha256: null, bytes: null };
    hle.finish_after = (regs, fn, args) => {
      rec.via = 'callback';
      rec.intended = args.d0 >>> 0;
      rec.callback = fn >>> 0;
      holder.queue.push(rec);
      this.observe(fn, (_lab, rr) => {
        const job = holder.queue.shift();
        if (job) job.status = rr.d0 >>> 0;
      }, 'obs-save-cb-' + (fn >>> 0).toString(16));
      return origAfter(regs, fn, args);
    };
    hle.finish = (regs, args = {}) => {
      if (rec.via === null) {
        rec.via = 'return';
        rec.intended = (args.d0 ?? 0) >>> 0;
        rec.status = rec.intended;
      }
      return origFinish(regs, args);
    };
    try { return orig.call(this, hle, r, posted); }
    finally {
      hle.finish_after = origAfter;
      hle.finish = origFinish;
      const saves = this.store_log && this.store_log.nvram ? this.store_log.nvram.saves : null;
      if (saves && saves.length > before) {
        const row = saves[saves.length - 1];
        rec.store = row.store;
        rec.from = row.from;
        rec.posted = !!row.posted;
        const img = Buffer.from(this.sim.read(r.a0 >>> 0, r.d0 >>> 0));
        rec.bytes = img.length;
        rec.sha256 = createHash('sha256').update(img).digest('hex');
        holder.events.push(rec);
      }
    }
  };
  proto.__t8SaveWitness = true;
}

const IMPORT_RE = /(?:from\s+|import\s*\(\s*|import\s+)['"]([^'"]+)['"]/g;
const USE_RE = /use\(\s*['"]([^'"]+)['"]\s*\)/g;
function resolveSpec(fromFile, spec) {
  if (!spec.startsWith('.')) return null;
  const base = resolve(dirname(fromFile), spec);
  for (const candidate of [base, base + '.mjs', base + '.js', join(base, 'index.mjs')]) {
    if (existsSync(candidate) && statSync(candidate).isFile()) return candidate;
  }
  return null;
}
function inventory(files) {
  const seen = new Map();
  const queue = [...files];
  while (queue.length) {
    const cur = queue.pop();
    if (!cur || seen.has(cur) || !existsSync(cur)) continue;
    const data = readFileSync(cur);
    seen.set(cur, { sha256: createHash('sha256').update(data).digest('hex'), bytes: data.length });
    const text = data.toString('utf8');
    for (const re of [IMPORT_RE, USE_RE]) {
      re.lastIndex = 0;
      let match;
      while ((match = re.exec(text))) {
        const spec = match[1];
        const next = spec.startsWith('.') ? resolveSpec(cur, spec) : resolve(checkout, 'emu', spec);
        if (next && existsSync(next)) queue.push(next);
      }
    }
  }
  for (const extra of dynamicImports) {
    if (existsSync(extra) && !seen.has(extra)) {
      const data = readFileSync(extra);
      seen.set(extra, { sha256: createHash('sha256').update(data).digest('hex'), bytes: data.length });
    }
  }
  return [...seen.entries()].map(([path, meta]) => ({ path: path.replaceAll('\\', '/'), ...meta, hashed: 'execution' }));
}

async function main() {
  const poseFile = resolve('ref/tasks/T7-orientation-producer/run-20261119-072701/work/scripts/pose.mjs');
  const poseHash = createHash('sha256').update(readFileSync(poseFile)).digest('hex');
  const poseProblems = [];
  if (poseHash !== POSE_SHA) poseProblems.push('pose hash expected ' + POSE_SHA + ' actual ' + poseHash);
  if (table.poseSha256 !== POSE_SHA) poseProblems.push('table pose hash');
  emit({
    id: tag + '-pose-import', step: 'pose-import', pass: poseProblems.length === 0, problems: poseProblems,
    expected: { sha256: POSE_SHA }, actual: { sha256: poseHash },
  });
  if (poseProblems.length) throw new Error(tag + '-pose-import');

  process.env.OM_EMU_MODEL = 'E147';
  const menuHref = pathToFileURL(resolve(checkout, 'emu/src/lab/menu.mjs')).href;
  const modelHref = pathToFileURL(resolve(checkout, 'emu/src/fw/model.mjs')).href;
  const pngHref = pathToFileURL(resolve(checkout, 'emu/checks/lib/png.mjs')).href;
  const rgbHref = pathToFileURL(resolve(checkout, 'emu/src/lab/display.mjs')).href;
  dynamicImports.push(resolve(checkout, 'emu/src/lab/menu.mjs'), resolve(checkout, 'emu/src/fw/model.mjs'), resolve(checkout, 'emu/checks/lib/png.mjs'), resolve(checkout, 'emu/src/lab/display.mjs'));
  const menuMod = await import(menuHref);
  const modelMod = await import(modelHref);
  const pngMod = await import(pngHref);
  const rgbMod = await import(rgbHref);
  png = { write_png: pngMod.write_png, words_to_rgb: rgbMod.words_to_rgb };
  await installWitness(menuMod);

  const stores = {};
  for (const role of ROLES) {
    const nv = 'work/out/nvram-' + tag + '-' + role + '.json';
    const overlay = role !== 'k1';
    const hooksOn = role === 'c1' || role === 'c2';
    let saveSnap = null;
    const result = await runZone({
      checkout,
      outPath: 'work/out/session-' + tag + '-' + role + '.jsonl',
      tag: tag + '-' + role,
      candidate: overlay,
      help: overlay,
      rowLabel: overlay,
      fatalShots: true,
      nvramPath: nv,
      overlayCsv: overlay ? OVERLAY : null,
      explanation: hooksOn
        ? role + ' combined profile read and editor restore. EMULATOR-ONLY. Role: behaviour.'
        : (overlay
          ? role + ' combined overlay, no profile-read hook and no editor hooks, flag off. EMULATOR-ONLY. Role: behaviour.'
          : role + ' stock. No overlay.'),
      change: hooksOn ? 'EMULATOR-ONLY combined configuration. Role: behaviour.' : 'none',
      async drive(ctx) {
        const hooks = hooksOn ? installCombined(ctx, modelMod, menuMod) : null;
        const pose = attachPose(ctx.l);
        const brought = ctx.bringUp();
        ctx.emit('behaviour', {
          step: 'bring-up',
          label: 'EMULATOR-ONLY native bring-up 0x6071181e, 0x608fe1b0, 0x609df7e4, task 105. Role: behaviour.',
          ...brought,
        });
        ctx.s.switch_input('lever', 1);
        ctx.s.camapp.pump();
        ctx.idle(500);
        const { A } = modelMod;
        const api = A(0x50ac4afe);
        const argument = ctx.l.call(ctx.native(0x604050e5), { d0: 289, d1: 0 }, null, null, 200000).d0 >>> 0;
        ctx.l.call(api, { d0: 289, d1: argument }, null, null, 200000);
        ctx.l.call(api, { d0: 1712, d1: 0 }, null, null, 200000);
        ctx.idle(500);
        ctx.emit('behaviour', {
          step: 's-af',
          label: 'EMULATOR-ONLY test setup. Public focus API sets mode 289 to S-AF and 1712 to 0. Role: test setup.',
        });
        pose.setPose('landscape');
        pose.deliver();
        ctx.idle(600);
        setKey(ctx, 0x1db1, 0, 1);
        setKey(ctx, 0x1dc1, 0, 1);
        ctx.emit('behaviour', {
          step: 'link-on',
          label: 'EMULATOR-ONLY test setup. Setter writes 0x1db1[0]=1 and 0x1dc1[0]=1. The half-press zone is set with keys. Role: test setup.',
        });
        if (hooks) hooks.refresh();
        const sessionSteps = table.steps.filter((s) => s.phase === 'main' && s.who.includes(role));
        for (const step of sessionSteps) {
          if (step.action === 'enter') {
            if (!hooks) throw new Error('editor step without hooks ' + step.id);
            hooks.enter();
          } else if (step.action === 'key') ctx.press(step.key);
          else if (step.action === 'dial') {
            ctx.s.dial_input(step.dial, 1);
            ctx.s.camapp.pump();
            ctx.idle(500);
          } else if (step.action === 'edge') {
            if (hooks) hooks.refresh();
            ctx.key(step.key, step.dir);
            ctx.idle(250);
          } else if (step.action === 'pose') {
            pose.setPose(step.key);
            pose.deliver();
            ctx.idle(600);
            setKey(ctx, 0x1db1, 0, 1);
            setKey(ctx, 0x1dc1, 0, 1);
            if (hooks) hooks.refresh();
            ctx.emit('behaviour', {
              step: step.id,
              label: 'EMULATOR-ONLY test setup. pose.mjs stand-in, then the link setters are written again. Role: test setup.',
            });
          } else if (step.action === 'size-setup') {
            const buf = Buffer.from([4]);
            ctx.l.sim.write(EXT + 0x08, buf);
            ctx.l.sim.write(EXT_CACHED + 0x08, buf);
            ctx.emit('behaviour', {
              step: step.id,
              label: 'EMULATOR-ONLY test setup. The direct screen cannot set mirror 0x9a41[0]. Write 4 at 0xa031eeb8 and 0x6031eeb8. Role: test setup.',
            });
          } else if (step.action === 'save-mark') saveSnap = holder.events.length;
          else if (step.action === 'save-witness') ctx.idle(1200);
          const view = capture(ctx, role, step.id);
          const actual = snapshot(ctx, view);
          const poseNow = pose.read();
          poseNow.word = ctx.l.sim.u32(POSE) >>> 0;
          if (step.action === 'save-witness') {
            if (saveSnap === null) throw new Error('save mark missing');
            const added = holder.events.slice(saveSnap);
            const file = readStore(resolve(nv));
            const judged = judgeFreshSaves(added, file);
            actual.persisted = PERSIST.map((off) => file.M.readUInt32LE(off));
            actual.added = added.map((ev) => ({ store: ev.store, via: ev.via, posted: ev.posted, status: ev.status, sha256: ev.sha256, bytes: ev.bytes }));
            actual.saveProblems = judged.problems;
          }
          const judgedStep = judgeStep(role, step, actual, poseNow);
          if (step.action === 'save-witness' && actual.saveProblems) {
            for (const p of actual.saveProblems) judgedStep.problems.push('save ' + p);
          }
          emit({
            id: role + '-' + step.id, role, step: step.action, key: step.key || null, dir: step.dir || null,
            editor: !!step.editor, pass: judgedStep.problems.length === 0, problems: judgedStep.problems,
            expected: judgedStep.expected, actual,
          });
          if (judgedStep.problems.length) throw new Error(role + '-' + step.id);
        }
      },
    });
    if (!result.ok) throw new Error(role + ' main ' + result.failed);
    stores[role] = readStore(resolve(nv));

    const reopenSteps = table.steps.filter((s) => s.phase === 'reopen' && s.who.includes(role));
    const re = await runZone({
      checkout,
      outPath: 'work/out/session-' + tag + '-' + role + '-reopen.jsonl',
      tag: tag + '-' + role + '-reopen',
      candidate: overlay,
      help: overlay,
      rowLabel: overlay,
      fatalShots: true,
      nvramPath: nv,
      overlayCsv: overlay ? OVERLAY : null,
      explanation: role + ' reopen on its own store.',
      change: hooksOn ? 'EMULATOR-ONLY combined configuration. Role: behaviour.' : 'none',
      async drive(ctx) {
        const hooks = hooksOn ? installCombined(ctx, modelMod, menuMod) : null;
        const brought = ctx.bringUp();
        ctx.emit('behaviour', {
          step: 'bring-up',
          label: 'EMULATOR-ONLY native bring-up 0x6071181e, 0x608fe1b0, 0x609df7e4, task 105. Role: behaviour.',
          ...brought,
        });
        ctx.s.switch_input('lever', 1);
        ctx.s.camapp.pump();
        ctx.idle(500);
        const { A } = modelMod;
        const api = A(0x50ac4afe);
        const argument = ctx.l.call(ctx.native(0x604050e5), { d0: 289, d1: 0 }, null, null, 200000).d0 >>> 0;
        ctx.l.call(api, { d0: 289, d1: argument }, null, null, 200000);
        ctx.l.call(api, { d0: 1712, d1: 0 }, null, null, 200000);
        ctx.idle(500);
        setKey(ctx, 0x1db1, 0, 1);
        setKey(ctx, 0x1dc1, 0, 1);
        if (hooks) hooks.refresh();
        for (const step of reopenSteps) {
          if (step.action === 'enter') {
            if (!hooks) throw new Error('editor step without hooks ' + step.id);
            hooks.enter();
          } else if (step.action === 'edge') {
            if (hooks) hooks.refresh();
            ctx.key(step.key, step.dir);
            ctx.idle(250);
          }
          const view = capture(ctx, role, 're-' + step.id);
          const actual = snapshot(ctx, view);
          const judgedStep = judgeStep(role, step, actual, null);
          emit({
            id: role + '-' + step.id, role, step: step.action, pass: judgedStep.problems.length === 0,
            problems: judgedStep.problems, expected: judgedStep.expected, actual,
          });
          if (judgedStep.problems.length) throw new Error(role + '-' + step.id);
        }
      },
    });
    if (!re.ok) throw new Error(role + ' reopen ' + re.failed);
  }

  if (mode === 'accept') {
    for (const role of ['c1', 'c2']) {
      const diffs = compareStores(stores[role], stores.k2);
      const problems = [];
      if (diffs.length) problems.push('store ' + diffs.length);
      emit({
        id: role + '-store', role, step: 'store', pass: problems.length === 0, problems,
        expected: { diffs: [] }, actual: { diffs, count: diffs.length },
      });
      if (problems.length) throw new Error(role + '-store');
    }
  }
  emit({ id: tag + '-done', step: 'done', pass: true, ok: true, problems: [], expected: { ok: true }, actual: { ok: true } });
}

try {
  await main();
} catch (error) {
  emit({
    id: tag + '-done', step: 'done', pass: false, ok: false,
    problems: [String(error && error.message ? error.message : error)],
    expected: { ok: true }, actual: { ok: false, error: String(error && error.stack ? error.stack : error) },
  });
  process.exitCode = 1;
} finally {
  if (!existsSync(inventoryPath)) {
    const rows = inventory([resolve('work/scripts/accept_t8_v1.mjs')]);
    writeFileSync(inventoryPath, JSON.stringify({ tag, rows }, null, 2) + '\n');
  }
}
